require 'aws-sdk-s3'

# Description: Sublayer::Action responsible for uploading a specified file to an AWS S3 bucket.
# This action facilitates storing text, media, or generated files from other actions 
# and making them easily accessible remotely.
#
# It is initialized with a bucket_name, file_path, and an optional key for the object in S3.
# It uploads the file to the specified S3 bucket and returns the object URL upon success.
#
# Example usage: When you want to store files generated by AI processes in AWS S3 for easy access.

class AWSS3FileUploadAction < Sublayer::Actions::Base
  def initialize(bucket_name:, file_path:, key: nil)
    @bucket_name = bucket_name
    @file_path = file_path
    @key = key || File.basename(file_path)
    @s3_client = Aws::S3::Client.new
  end

  def call
    upload_file_to_s3
  rescue Aws::S3::Errors::ServiceError => e
    error_message = "AWS S3 error during file upload: #{e.message}"
    Sublayer.configuration.logger.log(:error, error_message)
    raise StandardError, error_message
  rescue StandardError => e
    error_message = "Error uploading file to AWS S3: #{e.message}"
    Sublayer.configuration.logger.log(:error, error_message)
    raise e
  end

  private

  def upload_file_to_s3
    file = File.open(@file_path, 'rb')
    begin
      @s3_client.put_object(
        bucket: @bucket_name,
        key: @key,
        body: file
      )
      object_url = "https://#{@bucket_name}.s3.amazonaws.com/#{@key}"
      Sublayer.configuration.logger.log(:info, "File uploaded successfully to #{object_url}")
      object_url
    ensure
      file.close if file
    end
  end
end
